SELECT 
FROM tb_warehouse
WHERE tenant_id = #{tenantId}

    AND (
        warehouse_code ILIKE '%' || #{keyword} || '%'
        OR warehouse_name ILIKE '%' || #{keyword} || '%'
    )


    AND warehouse_type = #{warehouseType}


    AND disuse_at = #{disuseAt}

ORDER BY warehouse_code ASC, warehouse_id ASC

SELECT 
FROM tb_warehouse
WHERE warehouse_id = #{warehouseId}
  AND tenant_id = #{tenantId}

SELECT warehouse_id
FROM tb_warehouse
WHERE tenant_id = #{tenantId}
  AND warehouse_code = #{warehouseCode}

    AND warehouse_id != #{excludeWarehouseId}

LIMIT 1
